#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ir.h"
#include "ast.h"
#include "codegen.h"
#include "codegen_vm.h"

/* yyparse is generated by yacc */
int yyparse(void);

/* yyin is the scanner's input stream (from flex) */
extern FILE *yyin;
/* root comes from parser.y */
extern astnode *root;
/* ir_head from the ir.h file */
extern IRInstruction *ir_head;

int main(int argc, char **argv) {
    const char *in = NULL;
    const char *out = "out.tbc";
    int verbose = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) out = argv[++i];
        else if (strcmp(argv[i], "-v") == 0) verbose = 1;
        else in = argv[i];
    }

    if (!in) {
        fprintf(stderr, "usage: %s <input.tny> [-o output.tbc] [-v]\n", argv[0]);
        return 1;
    }

    yyin = fopen(in, "r");
    if (!yyin) {
        perror(in);
        return 1;
    }

    if (yyparse() != 0) {
        fprintf(stderr, "Parsing failed.\n");
        return 1;
    }

    //print_ast(root, 0);
    generate_ir(root);

    if (verbose) {
        print_ir();
        generate_code(ir_head);
    }

    if (generate_bytecode(ir_head, out) != 0) return 1;
    return 0;
}
// End
